import json,re
from datetime import datetime,timezone
SRC='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl'
OUT='/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/order-512/h2-context.md'
SKIP=('<','Another Claude session sent a message','This session is being continued','[SYSTEM','Base directory for this skill','Called the Read tool')
def txt(o):
    c=o['message']['content']
    if isinstance(c,str): return c
    return '\n'.join(b.get('text','') for b in c if isinstance(b,dict) and b.get('type')=='text')
msgs=[]
for l in open(SRC):
    try:o=json.loads(l)
    except: continue
    if o.get('isSidechain') or o.get('type') not in('user','assistant'): continue
    m=o.get('message') or {}
    c=m.get('content')
    if o['type']=='user':
        if isinstance(c,list) and not any(isinstance(b,dict) and b.get('type')=='text' for b in c): continue
        t=txt(o)
        if not t.strip() or t.lstrip().startswith(SKIP): continue
        sp='Pavol'
    else:
        if not isinstance(c,list): 
            t=c if isinstance(c,str) else ''
        else: t=txt(o)
        if not t.strip(): continue
        sp='Coordinator'
    msgs.append((o['timestamp'],sp,t))
msgs.sort(key=lambda x:x[0])
def D(s):return datetime.fromisoformat(s.replace('Z','+00:00'))
def dt(*a):return datetime(*a,tzinfo=timezone.utc)
W=[('Window 1: 2026-11-13 21:00 to 2026-11-14 06:00 UTC',dt(2026,11,13,21),dt(2026,11,14,6)),
('Window 2: 2026-11-16 00:00 to 03:00 UTC',dt(2026,11,16,0),dt(2026,11,16,3)),
('Window 3: 2026-11-16 22:30 to 2026-11-17 01:00 UTC',dt(2026,11,16,22,30),dt(2026,11,17,1))]
K=re.compile(r"carrier|which class (holds|carries)|FZZ32|hand-written run-time|run-time class|\bpayload|\bboxing|\bboxed|value object ZZ32|five number objects|UnsignedLong|\bBigNum\b|merge of the number traits|duality of names|prelude|\bway ?\(?[ABCD]\b|\bways? \(?[ab]\)|\bfork H2|\bH2\b",re.I)
K2=re.compile(r"carrier|FZZ32|payload|prelude|value object",re.I)
def hdr(m):return f"### {D(m[0]).strftime('%Y-%m-%d %H:%M:%S')} — {m[1]}\n\n{m[2]}\n"
out=[];counts=[]
for name,a,b in W:
    idx=[i for i,m in enumerate(msgs) if a<=D(m[0])<b]
    sel=set()
    for i in idx:
        if K.search(msgs[i][2]):
            sel.add(i)
            if msgs[i][1]=='Coordinator':
                j=i+1
                while j<len(msgs) and msgs[j][1]!='Pavol': j+=1
                if j<len(msgs): sel.add(j)
    # Pavol matching: add coordinator before only if Pavol msg answers... include preceding coordinator for Pavol-matched too
    for i in list(sel):
        if msgs[i][1]=='Pavol':
            j=i-1
            while j>=0 and msgs[j][1]!='Coordinator': j-=1
            if j>=0: sel.add(j)
    s=sorted(sel);counts.append(len(s))
    out.append(f"## {name} ({len(s)} messages)\n\n"+"\n".join(hdr(msgs[i]) for i in s))
# other mentions
sel=set()
for i,m in enumerate(msgs):
    if m[1]=='Pavol' and D(m[0])>=dt(2026,11,5) and K2.search(m[2]):
        j=i-1
        while j>=0 and msgs[j][1]!='Coordinator': j-=1
        sel.add(i)
        if j>=0: sel.add(j)
s=sorted(sel);counts.append(len(s))
out.append(f"## Other mentions ({len(s)} messages)\n\n"+"\n".join(hdr(msgs[i]) for i in s))
head=f"Windows: {W[0][0]}; {W[1][0]}; {W[2][0]}; whole transcript 2026-11-07 (first line) to end. Counts: {counts[0]}, {counts[1]}, {counts[2]}, other {counts[3]}.\n\n"
open(OUT,'w').write(head+"\n".join(out))
print(counts,len(msgs))
